from __future__ import annotations

import itertools as it
import sys
from collections.abc import Iterable

from ..mobject.mobject import Mobject
from ..utils.iterables import remove_list_redundancies

__all__ = ["extract_mobject_family_members"]


def extract_mobject_family_members(
    mobjects: Iterable[Mobject],
    use_z_index: bool = False,
    only_those_with_points: bool = False,
) -> list[Mobject]:
    """Returns a list of the types of mobjects and their family members present.
    A "family" in this context refers to a mobject, its submobjects, and their
    submobjects, recursively.

    Parameters
    ----------
    mobjects
        The Mobjects currently in the Scene
    only_those_with_points
        Whether or not to only do this for
        those mobjects that have points. By default False

    Returns
    -------
    list
        list of the mobjects and family members.
    """
    if only_those_with_points:
        method = Mobject.family_members_with_points
    else:
        method = Mobject.get_family
    mobjects = list(mobjects)
    extracted_mobjects = _families_in_one_walk(mobjects)
    if extracted_mobjects is None:
        extracted_mobjects = remove_list_redundancies(
            list(it.chain(*(method(m) for m in mobjects))),
        )
    elif only_those_with_points:
        extracted_mobjects = [m for m in extracted_mobjects if m.get_num_points() > 0]
    if use_z_index:
        return sorted(extracted_mobjects, key=lambda m: m.z_index)
    return extracted_mobjects


def _families_in_one_walk(mobjects: list[Mobject]) -> list[Mobject] | None:
    """The families of ``mobjects`` joined, keeping each member's last place.

    The camera calls extract_mobject_family_members every frame with the
    scene's mobjects already flattened, so asking each one for its family
    went over most of them again and again (the 200 squares of a VGroup
    once for the group and once each). This goes over each member once.

    Joining the families and keeping the last of each repeat is the same
    as walking the joined lists backwards and keeping the first. Backwards,
    a mobject comes after every member of its family, so once it has been
    met its whole family has, and meeting it again skips it whole. Returns None, for the caller's own loop, if a class has
    its own get_family or a family is nested too deep (or contains itself).
    """
    own = Mobject.get_family
    depth_limit = sys.getrecursionlimit()
    used: set[Mobject] = set()
    out: list[Mobject] = []
    for root in reversed(mobjects):
        if root in used:
            continue
        if type(root).get_family is not own:
            return None
        stack = [(root, reversed(root.submobjects))]
        while stack:
            node, children = stack[-1]
            for child in children:
                if child in used:
                    continue
                if type(child).get_family is not own or len(stack) >= depth_limit:
                    return None
                stack.append((child, reversed(child.submobjects)))
                break
            else:
                stack.pop()
                if node not in used:
                    used.add(node)
                    out.append(node)
    out.reverse()
    return out
